# mto VERSION completions for powershell, generated by `mto completions powershell`; do not edit.
# Run it from your profile ($PROFILE) to complete mto's arguments.

Register-ArgumentCompleter -Native -CommandName 'mto', 'mto.exe' -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    # The flags that may come before any command (''), after a command, and after a
    # subcommand.
    $flags = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $flags[''] = @('--check', '-d', '--dry-run', '--emit', '-l', '--files-with-diff', '--follow-links', '-R', '--recursive', '--skip-children', '--stdin-filepath', '--config', '--config-path', '--edition', '--print-config', '--style-edition', '--unstable-features', '--allow-dirty', '--unguarded', '--no-history', '--color', '--dbg', '-q', '--quiet', '-v', '--verbose', '-h', '--help', '--man', '-V', '--version')
    $flags['init'] = @('-h', '--help')
    $flags['config'] = @('-h', '--help')
    $flags['config path'] = @('-h', '--help', '--config', '--config-path', '--edition', '--style-edition')
    $flags['config print'] = @('-h', '--help', '--current', '--default', '--minimal', '--user', '--config', '--config-path', '--edition', '--style-edition')
    $flags['config options'] = @('-h', '--help', '--toml')
    $flags['history'] = @('-h', '--help', '--all')
    $flags['history show'] = @('-h', '--help')
    $flags['history prune'] = @('-h', '--help', '--keep', '--older-than')
    $flags['restore'] = @('-h', '--help', '--force')
    $flags['doctor'] = @('-h', '--help')
    $flags['doctor on'] = @('-h', '--help')
    $flags['doctor off'] = @('-h', '--help')
    $flags['doctor holds'] = @('-h', '--help')
    $flags['doctor release'] = @('-h', '--help')
    $flags['report'] = @('-h', '--help')
    $flags['report show'] = @('-h', '--help')
    $flags['report save'] = @('-h', '--help', '--with-file')
    $flags['report send'] = @('-h', '--help')
    $flags['report prune'] = @('-h', '--help')
    $flags['debug'] = @('-h', '--help')
    $flags['debug tokens'] = @('-h', '--help', '--edition')
    $flags['debug tree'] = @('-h', '--help', '--edition')
    $flags['debug layout'] = @('-h', '--help', '--edition')
    $flags['completions'] = @('-h', '--help')
    $flags['completions install'] = @('-h', '--help', '--dir', '-d', '--dry-run')
    $flags['completions uninstall'] = @('-h', '--help', '--dir', '-d', '--dry-run')
    $flags['completions status'] = @('-h', '--help')
    # What each flag, command and subcommand does.
    $help = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $help['--check'] = 'Print a diff for every file that would change; exit 1 if any'
    $help['-d'] = 'List the files that would change, without writing'
    $help['--dry-run'] = 'List the files that would change, without writing'
    $help['--emit'] = 'Write the files (default), print them, or report changes as JSON'
    $help['-l'] = 'Name the files that change (or would, with --check) instead of showing how'
    $help['--files-with-diff'] = 'Name the files that change (or would, with --check) instead of showing how'
    $help['--follow-links'] = 'Also follow symlinked files and directories'
    $help['-R'] = 'Format every .rs file under the current directory'
    $help['--recursive'] = 'Format every .rs file under the current directory'
    $help['--skip-children'] = 'A file argument is that file alone, not the modules it declares'
    $help['--stdin-filepath'] = 'With -: where the source belongs, for its settings and in messages'
    $help['--config'] = 'Set settings for this run, over every file'
    $help['--config-path'] = 'Use only this configuration file; search for no other'
    $help['--edition'] = 'The Rust edition, over Cargo.toml and configuration files'
    $help['--print-config'] = 'Print the formatting settings as the standard formatter prints them, and exit'
    $help['--style-edition'] = 'The style edition, which decides the defaults'
    $help['--unstable-features'] = 'Accepted for compatibility; mto applies every setting on every channel'
    $help['--allow-dirty'] = 'With history off, rewrite files that have uncommitted changes'
    $help['--unguarded'] = 'Do not check this run with the build guard, nor hold back the edits it holds'
    $help['--no-history'] = 'Do not record this run in history (it cannot be restored)'
    $help['--color'] = 'Color the output (default: auto, only on a terminal)'
    $help['--dbg'] = 'Print how each file was split into items'
    $help['-q'] = 'Print only errors and what was asked for'
    $help['--quiet'] = 'Print only errors and what was asked for'
    $help['-v'] = 'Name each file as it is formatted'
    $help['--verbose'] = 'Name each file as it is formatted'
    $help['-h'] = 'Show this help and exit'
    $help['--help'] = 'Show this help and exit'
    $help['--man'] = 'Print the full manual'
    $help['-V'] = 'Print the version and exit'
    $help['--version'] = 'Print the version and exit'
    $help['--current'] = 'Every setting in effect, with its source (the default)'
    $help['--default'] = 'Every setting at its default'
    $help['--minimal'] = 'Only the settings that differ from their defaults'
    $help['--user'] = 'The user config''s settings'
    $help['--force'] = 'Also restore files changed since the run, and missing ones'
    $help['--toml'] = 'As a commented file, every setting at its default'
    $help['--all'] = 'List every project''s runs'
    $help['--keep'] = 'Keep only the newest N runs'
    $help['--with-file'] = 'Add the whole file the bug was found in'
    $help['--dir'] = 'Use this folder instead of the shell''s own'
    $help['--older-than'] = 'Remove runs this old: 30 (days), 2w, 12h'
    $help['init'] = 'Write a default mto.toml'
    $help['config'] = 'Show the configuration that applies in a folder, or every setting'
    $help['config path'] = 'List the configuration files that apply, and the history folder'
    $help['config print'] = 'Show every setting in effect, with where it came from'
    $help['config options'] = 'List every setting a configuration file may hold'
    $help['history'] = 'List, show or prune the runs that wrote files'
    $help['history show'] = 'List one run''s files and where each stands now'
    $help['history prune'] = 'Remove old runs'
    $help['restore'] = 'Undo a run'
    $help['doctor'] = 'Guard the build against mto''s edits, or find the edit that broke it'
    $help['doctor on'] = 'Turn the build guard on'
    $help['doctor off'] = 'Turn the build guard off'
    $help['doctor holds'] = 'List the edits the guard holds back'
    $help['doctor release'] = 'Drop one held edit, or all'
    $help['report'] = 'The bug reports mto keeps when it finds a bug in itself'
    $help['report show'] = 'Print one report'
    $help['report save'] = 'Write one report to a file'
    $help['report send'] = 'Open a new issue filled in with one report'
    $help['report prune'] = 'Remove every report'
    $help['debug'] = 'Print what mto sees in a file, or where and why it leaves code as written'
    $help['debug tokens'] = 'Print the tokens of a file'
    $help['debug tree'] = 'Print the syntax tree of a file'
    $help['debug layout'] = 'Say where the formatter leaves code as written, and why'
    $help['completions'] = 'Print or install the completions for a shell'
    $help['completions install'] = 'Write the script where the shell loads completions from'
    $help['completions uninstall'] = 'Remove the script mto wrote'
    $help['completions status'] = 'Say where each shell''s script is, and whether it is current'
    # The flags followed by a value, and what the value completes to.
    $takesValue = @('--emit', '--stdin-filepath', '--config', '--config-path', '--edition', '--print-config', '--style-edition', '--color', '--keep', '--dir', '--older-than')
    # A flag's values, when they are a fixed set.
    $values = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $values['--emit'] = @('files', 'stdout', 'json')
    $values['--edition'] = @('2015', '2018', '2021', '2024')
    $values['--print-config'] = @('default', 'minimal', 'current')
    $values['--style-edition'] = @('2015', '2018', '2021', '2024', '2027')
    $values['--color'] = @('always', 'never', 'auto')
    # The flags that take a path.
    $paths = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $paths['--stdin-filepath'] = 'files'
    $paths['--config-path'] = 'files'
    $paths['--dir'] = 'dirs'
    $commands = @('init', 'config', 'history', 'restore', 'doctor', 'report', 'debug', 'completions')
    # Each command's subcommands.
    $subcommands = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $subcommands['config'] = @('path', 'print', 'options')
    $subcommands['history'] = @('show', 'prune')
    $subcommands['doctor'] = @('on', 'off', 'holds', 'release')
    $subcommands['report'] = @('show', 'save', 'send', 'prune')
    $subcommands['debug'] = @('tokens', 'tree', 'layout')
    $subcommands['completions'] = @('install', 'uninstall', 'status')
    # What a command's arguments complete to, after any subcommand.
    $operandPaths = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $operandPaths['init'] = 'dirs'
    $operandPaths['config path'] = 'dirs'
    $operandPaths['config print'] = 'dirs'
    $operandPaths['restore'] = 'files'
    $operandPaths['report save'] = 'files'
    $operandPaths['debug tokens'] = 'files'
    $operandPaths['debug tree'] = 'files'
    $operandPaths['debug layout'] = 'files'
    $operandWords = [System.Collections.Hashtable]::new([System.StringComparer]::Ordinal)
    $operandWords['completions'] = @('bash', 'zsh', 'fish', 'powershell')
    $operandWords['completions install'] = @('bash', 'zsh', 'fish', 'powershell')
    $operandWords['completions uninstall'] = @('bash', 'zsh', 'fish', 'powershell')
    $operandWords['completions status'] = @('bash', 'zsh', 'fish', 'powershell')
    # The settings --config takes, and their values when they are a fixed set.
    $settings = [ordered]@{
        'array_width' = @()
        'attr_fn_like_width' = @()
        'binop_separator' = @('Front', 'Back')
        'blank_lines_lower_bound' = @()
        'blank_lines_upper_bound' = @()
        'brace_style' = @('AlwaysNextLine', 'PreferSameLine', 'SameLineWhere')
        'chain_width' = @()
        'color' = @('Always', 'Never', 'Auto')
        'combine_control_expr' = @('true', 'false')
        'comment_width' = @()
        'condense_wildcard_suffixes' = @('true', 'false')
        'control_brace_style' = @('AlwaysSameLine', 'ClosingNextLine', 'AlwaysNextLine')
        'disable_all_formatting' = @('true', 'false')
        'doc_comment_code_block_small_heuristics' = @('Inherit', 'Off', 'Max', 'Default')
        'doc_comment_code_block_width' = @()
        'edition' = @('2015', '2018', '2021', '2024')
        'emit_mode' = @('Files', 'Stdout', 'Coverage', 'Checkstyle', 'Json', 'ModifiedLines', 'Diff')
        'empty_item_single_line' = @('true', 'false')
        'enum_discrim_align_threshold' = @()
        'error_on_line_overflow' = @('true', 'false')
        'error_on_unformatted' = @('true', 'false')
        'float_literal_trailing_zero' = @('Preserve', 'Always', 'IfNoPostfix', 'Never')
        'fn_call_width' = @()
        'fn_params_layout' = @('Compressed', 'Tall', 'Vertical')
        'fn_single_line' = @('true', 'false')
        'force_explicit_abi' = @('true', 'false')
        'force_multiline_blocks' = @('true', 'false')
        'format_code_in_doc_comments' = @('true', 'false')
        'format_generated_files' = @('true', 'false')
        'format_macro_bodies' = @('true', 'false')
        'format_macro_matchers' = @('true', 'false')
        'format_strings' = @('true', 'false')
        'generated_marker_line_search_limit' = @()
        'group_imports' = @('Preserve', 'StdExternalCrate', 'One')
        'hard_tabs' = @('true', 'false')
        'hex_literal_case' = @('Preserve', 'Upper', 'Lower')
        'ignore' = @()
        'imports_granularity' = @('Preserve', 'Crate', 'Module', 'Item', 'One')
        'imports_indent' = @('Visual', 'Block')
        'imports_layout' = @('Vertical', 'Horizontal', 'HorizontalVertical', 'Mixed')
        'indent_style' = @('Visual', 'Block')
        'inline_attribute_width' = @()
        'make_backup' = @('true', 'false')
        'match_arm_blocks' = @('true', 'false')
        'match_arm_indent' = @('true', 'false')
        'match_arm_leading_pipes' = @('Always', 'Never', 'Preserve')
        'match_block_trailing_comma' = @('true', 'false')
        'max_width' = @()
        'merge_derives' = @('true', 'false')
        'newline_style' = @('Auto', 'Windows', 'Unix', 'Native')
        'normalize_comments' = @('true', 'false')
        'normalize_doc_attributes' = @('true', 'false')
        'overflow_delimited_expr' = @('true', 'false')
        'remove_nested_parens' = @('true', 'false')
        'reorder_impl_items' = @('true', 'false')
        'reorder_imports' = @('true', 'false')
        'reorder_modules' = @('true', 'false')
        'required_version' = @()
        'short_array_element_width_threshold' = @()
        'show_parse_errors' = @('true', 'false')
        'single_line_if_else_max_width' = @()
        'single_line_let_else_max_width' = @()
        'skip_children' = @('true', 'false')
        'skip_macro_invocations' = @()
        'space_after_colon' = @('true', 'false')
        'space_before_colon' = @('true', 'false')
        'spaces_around_ranges' = @('true', 'false')
        'struct_field_align_threshold' = @()
        'struct_lit_single_line' = @('true', 'false')
        'struct_lit_width' = @()
        'struct_variant_width' = @()
        'style_edition' = @('2015', '2018', '2021', '2024', '2027')
        'tab_spaces' = @()
        'trailing_comma' = @('Always', 'Never', 'Vertical')
        'trailing_semicolon' = @('true', 'false')
        'type_punctuation_density' = @('Compressed', 'Wide')
        'unstable_features' = @('true', 'false')
        'use_field_init_shorthand' = @('true', 'false')
        'use_small_heuristics' = @('Off', 'Max', 'Default')
        'use_try_shorthand' = @('true', 'false')
        'version' = @('One', 'Two')
        'where_single_line' = @('true', 'false')
        'wrap_comments' = @('true', 'false')
        'blank_lines_between_blocks' = @()
        'generated_markers' = @()
        'group_impls' = @('true', 'false')
        'ignore_dirs' = @()
        'impl_method_order' = @('written', 'trait')
        'import_grouping' = @('true', 'false')
        'import_sort' = @('style_edition', '2015', '2024')
        'layout' = @('true', 'false')
        'format' = @('true', 'false')
        'layout_generated_files' = @('true', 'false')
        'name_sort' = @('version', 'bytes', 'case_insensitive')
        'sort_alphabetically' = @('true', 'false')
        'sort_imports' = @('true', 'false')
        'test_module' = @('last', 'in_place')
        'trait_impl_order' = @()
        'trait_impl_sort' = @('name', 'original')
        'type_order' = @()
        'visibility_order' = @()
    }

    $result = {
        param($text, $tip)
        if ($text.StartsWith($wordToComplete, [System.StringComparison]::OrdinalIgnoreCase)) {
            $shown = $text
            if ($text -match '\s') { $shown = "'" + $text.Replace("'", "''") + "'" }
            if (-not $tip) { $tip = $text }
            [System.Management.Automation.CompletionResult]::new($shown, $text, 'ParameterValue', $tip)
        }
    }
    # Folders, and Rust files, or every file when no Rust file matches; only folders
    # when $kind is dirs.
    $pathsOf = {
        param($before, $typed, $kind)
        $parent = ''
        $cut = $typed.LastIndexOfAny([char[]]@('/', '\'))
        if ($cut -ge 0) { $parent = $typed.Substring(0, $cut + 1) }
        $items = @(Get-ChildItem -Path ($typed + '*') -Force -ErrorAction SilentlyContinue)
        $files = @()
        if ($kind -eq 'files') {
            $all = @($items | Where-Object { -not $_.PSIsContainer })
            $files = @($all | Where-Object { $_.Name -like '*.rs' })
            if ($files.Count -eq 0) { $files = $all }
        }
        foreach ($item in @($items | Where-Object { $_.PSIsContainer })) {
            & $result ($before + $parent + $item.Name + [System.IO.Path]::DirectorySeparatorChar) $item.Name
        }
        foreach ($item in $files) {
            & $result ($before + $parent + $item.Name) $item.Name
        }
    }
    # --config's pairs: the settings, then after `=` the setting's values.
    $settingsOf = {
        param($before, $typed)
        $head = ''
        $last = $typed
        $comma = $typed.LastIndexOf(',')
        if ($comma -ge 0) {
            $head = $typed.Substring(0, $comma + 1)
            $last = $typed.Substring($comma + 1)
        }
        $equals = $last.IndexOf('=')
        if ($equals -ge 0) {
            $key = $last.Substring(0, $equals)
            if ($settings.Contains($key)) {
                foreach ($value in $settings[$key]) {
                    & $result ($before + $head + $key + '=' + $value) $value
                }
            }
        } else {
            foreach ($key in $settings.Keys) { & $result ($before + $head + $key + '=') $key }
        }
    }
    $valueOf = {
        param($flag, $before, $typed)
        if ($values.Contains($flag)) {
            foreach ($value in $values[$flag]) { & $result ($before + $value) $value }
        } elseif ($paths.Contains($flag)) {
            & $pathsOf $before $typed $paths[$flag]
        } elseif ($flag -eq '--config') {
            & $settingsOf $before $typed
        }
    }

    # The command and subcommand given so far, and how many arguments followed them.
    $words = @($commandAst.CommandElements |
        Where-Object { $_.Extent.EndOffset -lt $cursorPosition } |
        ForEach-Object { $_.Extent.Text })
    $command = ''
    $sub = ''
    $operands = 0
    $expect = $null
    for ($i = 1; $i -lt $words.Count; $i++) {
        $word = $words[$i]
        if ($expect) { $expect = $null; continue }
        if ($word -eq '--') { return }
        if ($word -like '--*=*') { continue }
        if ($word.Length -gt 1 -and $word.StartsWith('-')) {
            if ($takesValue -ccontains $word) { $expect = $word }
            continue
        }
        if ($operands -eq 0 -and $command -eq '' -and $commands -ccontains $word) {
            $command = $word
        } elseif ($operands -eq 0 -and $command -ne '' -and $sub -eq '' -and
            $subcommands.Contains($command) -and $subcommands[$command] -ccontains $word) {
            $sub = $word
        } else {
            $operands++
        }
    }

    if ($expect) {
        & $valueOf $expect '' $wordToComplete
        return
    }
    if ($wordToComplete -like '--*=*') {
        $flag = $wordToComplete.Substring(0, $wordToComplete.IndexOf('='))
        & $valueOf $flag ($flag + '=') $wordToComplete.Substring($flag.Length + 1)
        return
    }
    $place = "$command $sub".Trim()
    if ($wordToComplete.StartsWith('-')) {
        foreach ($flag in $flags[$place]) { & $result $flag $help[$flag] }
        return
    }
    if ($command -eq '') {
        if ($operands -eq 0) {
            foreach ($name in $commands) { & $result $name $help[$name] }
        }
        & $pathsOf '' $wordToComplete 'files'
        return
    }
    if ($operands -eq 0 -and $sub -eq '' -and $subcommands.Contains($command)) {
        foreach ($name in $subcommands[$command]) { & $result $name $help["$command $name"] }
    }
    if ($operandWords.Contains($place)) {
        foreach ($value in $operandWords[$place]) { & $result $value $value }
    } elseif ($operandPaths.Contains($place)) {
        & $pathsOf '' $wordToComplete $operandPaths[$place]
    }
}
